nav=['日报工作台','周报工作台','历史汇报','个人信息','模型 API 设置']; icons=['▤','▦','◷','○','⚙']
def shell(active,title,desc,content):
    links=''.join(f'<div class="nav {"active" if x==active else ""}"><b>{i}</b>{x}</div>' for x,i in zip(nav,icons))
    return f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>{css}</style><body><div class="app"><aside class="side"><div class="brand"><span class="mark">方</span>汇报有方</div><div class="caption">我的工作空间</div>{links}<div class="sidebottom"><div class="avatar">林</div><div><strong>林晓</strong><div class="sub">产品经理 · 示例账号</div></div></div></aside><main class="main"><div class="top"><div class="crumb">我的工作空间　 /　 {title}</div><div class="topright"><span><i class="dot"></i>本机数据</span><div class="avatar">林</div></div></div><div class="canvas"><div class="heading"><div><h1>{title}</h1><p>{desc}</p></div><span class="badge">设计示例 · 非真实用户数据</span></div>{content}</div></main></div></body></html>'''
left='''<div class="panel"><div class="panelhead"><strong>整理今日工作</strong><span class="hint">先记录，再生成</span></div><div class="body"><div class="label">汇报日期</div><div class="date">2026 年 10 月 20 日，星期二 <span>▦</span></div><div class="space"></div><div class="label">工作内容 <span class="secondary">　与成果文件至少填写一项</span></div><div class="text">完成需求评审，整理会议结论；跟进研发排期，并更新项目计划。</div><div class="space"></div><div class="label">工作成果 <span class="secondary">　2 个文件</span></div><div class="upload"><span class="plus">＋</span><div><strong>添加成果文件</strong><small>支持拖拽上传，单个文件不超过 50 MB</small></div></div><div class="files"><div class="file"><span>▤　需求评审纪要.docx</span><i>移除</i></div><div class="file"><span>▤　项目计划.xlsx</span><i>移除</i></div></div><div class="actionrow"><button class="primary">生成日报</button><button class="outline">保存草稿</button><span class="note">生成前可继续修改素材</span></div></div></div>'''
preview='''<div class="panel"><div class="panelhead"><strong>汇报预览</strong><span class="status">待核对</span></div><div class="paper"><h2>本日工作汇报</h2><div class="meta">2026 年 10 月 20 日　 ·　 林晓 / 产品经理</div><h3>今日工作</h3><p><b>需求评审：</b>组织需求评审并整理会议结论，明确后续待确认事项。</p><p><b>项目推进：</b>跟进研发排期，更新项目计划并同步相关人员。</p><h3>需要核对</h3><p>请结合原始材料确认具体时间和负责人后再保存。</p></div><div class="paperfoot"><span>可直接编辑正文</span><span>内容由模型整理，请核对事实</span></div><div class="footerbuttons"><button class="outline">复制正文</button><button class="outline">下载成果压缩包</button><button class="primary">保存汇报</button></div></div>'''
(p/'daily.html').write_text(shell('日报工作台','日报工作台','记录今天的工作，生成并核对汇报。',f'<div class="grid">{left}{preview}</div>'),encoding='utf8')
weekly='''<div class="panel"><div class="panelhead"><strong>整理本周工作</strong><span class="hint">来源于已保存日报</span></div><div class="body"><div class="label">汇报周期</div><div class="date">‹　2026 年 10 月 19 日 — 10 月 25 日　› <span>▦</span></div><div class="space"></div><div class="label">本周汇报来源</div><div class="sources"><div class="stat"><b>2 <small>天</small></b><span>已保存日报</span></div><div class="stat"><b>2 <small>份</small></b><span>工作成果</span></div><div class="stat"><b>4 <small>项</small></b><span>工作记录</span></div></div><div class="source"><div><strong>10 月 20 日 · 周二</strong><small>需求评审、项目推进　·　2 份成果</small></div><span class="check">已关联</span></div><div class="source"><div><strong>10 月 19 日 · 周一</strong><small>需求整理、沟通协作　·　无附件</small></div><span class="check">已关联</span></div><div class="space"></div><div class="label">补充要求 <span class="secondary">　选填</span></div><div class="text" style="height:90px">按项目归类，突出关键进展。</div><div class="actionrow"><button class="primary">生成周报</button><button class="outline">保存草稿</button><span class="note">请先核对关联来源</span></div></div></div>'''
wp=preview.replace('本日工作汇报','本周工作汇报').replace('2026 年 10 月 20 日','10 月 19 日 — 10 月 25 日').replace('今日工作','本周工作')
(p/'weekly.html').write_text(shell('周报工作台','周报工作台','基于已保存的日报整理本周进展。',f'<div class="grid">{weekly}{wp}</div>'),encoding='utf8')
history='''<div class="panel"><div class="panelhead"><strong>已保存的汇报</strong><div class="listfilter"><span class="chip">全部</span><span class="chip plain">按日期筛选　▦</span></div></div><div class="table"><div class="tr head"><span>类型</span><span>汇报时间</span><span>状态</span><span>操作</span></div><div class="tr"><strong>日报</strong><span>2026 年 10 月 20 日</span><span class="tag">已保存</span><span>查看　›</span></div><div class="tr"><strong>日报</strong><span>2026 年 10 月 19 日</span><span class="tag">已保存</span><span>查看　›</span></div><div class="tr"><strong>周报</strong><span>10 月 12 日 — 10 月 18 日</span><span class="tag">已保存</span><span>查看　›</span></div></div><div style="padding:20px 26px;color:#829391;font-size:12px">示例记录仅用于展示页面结构</div></div>'''
(p/'history.html').write_text(shell('历史汇报','历史汇报','按日期查找已保存的日报与周报。',history),encoding='utf8')
profile='''<div class="panel settings"><div class="settingshead"><h2>汇报身份</h2><p>用于汇报署名与成果压缩包名称。</p></div><div class="settingbody"><div class="row"><label>姓名</label><div class="input">林晓</div></div><div class="row"><label>岗位</label><div class="input">产品经理</div></div><div class="row"><label>部门 <span class="secondary">选填</span></label><div class="input">产品研发部</div></div><div class="info">保存后，当前汇报署名和压缩包名称将使用更新后的信息。</div></div><div class="bottom"><button class="primary">保存个人信息</button></div></div>'''
api='''<div class="panel settings"><div class="settingshead"><h2>模型连接</h2><p>配置 OpenAI 兼容的 Chat Completions 接口。</p></div><div class="settingbody"><div class="row"><label>模型名称</label><div class="input">填写模型名称</div></div><div class="row"><label>API Base URL</label><div class="input">https://api.example.com/v1</div></div><div class="row"><label>API Key</label><div><div class="input">输入或更换 API Key　<span style="float:right">显示</span></div><p class="help">已保存的密钥不会回填；留空保存将保留原密钥。</p></div></div><div class="info">密钥加密保存在本机。生成汇报时，工作内容与可读取的成果将发送至所配置的模型服务。</div></div><div class="bottom"><button class="outline">测试已保存配置</button><button class="primary">保存模型设置</button></div></div>'''
(p/'profile.html').write_text(shell('个人信息','个人信息','管理汇报中的署名信息。',profile),encoding='utf8')
(p/'api.html').write_text(shell('模型 API 设置','模型 API 设置','连接你的模型服务，开始生成汇报。',api),encoding='utf8')
